create or replace view public.registry_missing_artist_latest_submission with (security_invoker = true) as select distinct on (split_part(source_note, ' ', 1)) split_part(split_part(source_note, ' ', 1), ':', 2) as legacy_slug, id as submission_id, review_status as submission_review_status, created_at as submission_created_at, reviewed_at as submission_reviewed_at from public.contributor_submissions where source_note like 'missing_artist_slug:%' order by split_part(source_note, ' ', 1), created_at desc;;
